from itertools import product

def norm(points):
 mn_r=min(r for r,c in points); mn_c=min(c for r,c in points)
 return tuple(sorted((r-mn_r,c-mn_c) for r,c in points))
def variants(points):
 out=set()
 for flip in [1,-1]:
  for k in range(4):
   q=[]
   for r,c in points:
    x,y=r, c*flip
    for _ in range(k): x,y=y,-x
    q.append((x,y))
   out.add(norm(q))
 return out
